import React, { useState, useEffect } from 'react';
import { Check, Download, Upload, Search, Filter, Plus } from 'lucide-react';

// Colors from your poster
const colors = {
  primary: '#f7abff',
  secondary: '#2f2a2f',
  accent: '#3CDFFF',
  darkAccent: '#620f87',
  light: '#f9f9f9',
  midGray: '#797979',
  successGreen: '#4ADE80',
  inProgressBlue: '#38BDF8',
  notStartedGray: '#6B7280'
};

const ShotList = () => {
  const [shots, setShots] = useState([]);
  const [filteredShots, setFilteredShots] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [sceneFilter, setSceneFilter] = useState('All');
  const [scenes, setScenes] = useState(['All']);
  const [loading, setLoading] = useState(true);

  // Fetch shots from API
  useEffect(() => {
    const fetchShots = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/shots');
        const data = await response.json();
        
        // If no shots exist yet, use sample data
        if (!data || data.length === 0) {
          const sampleShots = generateSampleShots();
          setShots(sampleShots);
          
          // Extract unique scenes for filtering
          const uniqueScenes = ['All', ...new Set(sampleShots.map(shot => shot.scene))];
          setScenes(uniqueScenes);
          
          setFilteredShots(sampleShots);
        } else {
          setShots(data);
          
          // Extract unique scenes for filtering
          const uniqueScenes = ['All', ...new Set(data.map(shot => shot.scene))];
          setScenes(uniqueScenes);
          
          setFilteredShots(data);
        }
        
        setLoading(false);
      } catch (error) {
        console.error('Error fetching shots:', error);
        const sampleShots = generateSampleShots();
        setShots(sampleShots);
        setFilteredShots(sampleShots);
        
        // Extract unique scenes for filtering
        const uniqueScenes = ['All', ...new Set(sampleShots.map(shot => shot.scene))];
        setScenes(uniqueScenes);
        
        setLoading(false);
      }
    };
    
    fetchShots();
  }, []);

  // Filter shots based on search term and filters
  useEffect(() => {
    let filtered = [...shots];
    
    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter(shot => 
        shot.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        shot.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        shot.scene.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    
    // Apply status filter
    if (statusFilter !== 'All') {
      filtered = filtered.filter(shot => shot.status === statusFilter);
    }
    
    // Apply scene filter
    if (sceneFilter !== 'All') {
      filtered = filtered.filter(shot => shot.scene === sceneFilter);
    }
    
    setFilteredShots(filtered);
  }, [searchTerm, statusFilter, sceneFilter, shots]);

  // Generate sample shot data
  const generateSampleShots = () => {
    return [
      { id: '001', scene: 'Opening', description: 'ECU Young Jax\'s fingers stumble over piano keys', status: 'Complete', notes: 'Perfect lighting achieved' },
      { id: '002', scene: 'Opening', description: 'CU Young Jax\'s face, concentrated on keys', status: 'In Progress', notes: 'Need facial animation refinement' },
      { id: '003', scene: 'Opening', description: 'WS Piano room showing Young Jax and Jett', status: 'Not Started', notes: 'Camera needs adjustment' },
      { id: '004', scene: 'Opening', description: 'MCU Jett smiling encouragingly at Young Jax', status: 'Not Started', notes: '' },
      { id: '005', scene: 'Opening', description: 'CU Young Jax\'s fingers beginning to play correctly', status: 'Not Started', notes: '' },
      { id: '006', scene: 'Black Sun Attack', description: 'WIDE Front door EXPLODING inward', status: 'Complete', notes: 'VFX complete' },
      { id: '007', scene: 'Black Sun Attack', description: 'CU Mother\'s terrified face screaming', status: 'In Progress', notes: 'Working on facial animation' },
      { id: '008', scene: 'Black Sun Attack', description: 'TRACKING SHOT following dark figures', status: 'Not Started', notes: '' },
      { id: '009', scene: 'Black Sun Attack', description: 'LOW ANGLE Jax being slammed to ground', status: 'Not Started', notes: '' },
      { id: '010', scene: 'Band Practice', description: 'WIDE Band playing first song together', status: 'Complete', notes: 'Audio synced perfectly' }
    ];
  };

  // Handle shot status change
  const handleStatusChange = async (id, newStatus) => {
    try {
      // Update shot in the backend (in a real app)
      // const response = await fetch(`http://localhost:5000/api/shots/${id}`, {
      //   method: 'PUT',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ status: newStatus })
      // });
      
      // For now, just update the local state
      const updatedShots = shots.map(shot => 
        shot.id === id ? { ...shot, status: newStatus } : shot
      );
      
      setShots(updatedShots);
    } catch (error) {
      console.error('Error updating shot status:', error);
    }
  };

  // Handle file import
  const handleFileImport = (event) => {
    const file = event.target.files[0];
    if (file) {
      // Here we would implement the Excel file reading logic
      // For now, just show an alert
      alert(`File "${file.name}" selected. Import functionality will be implemented soon.`);
    }
  };

  // Generate a status badge component based on status
  const StatusBadge = ({ status }) => {
    let bgColor, textColor;
    
    switch (status) {
      case 'Complete':
        bgColor = 'bg-green-900';
        textColor = 'text-green-300';
        break;
      case 'In Progress':
        bgColor = 'bg-blue-900';
        textColor = 'text-blue-300';
        break;
      default:
        bgColor = 'bg-gray-800';
        textColor = 'text-gray-400';
    }
    
    return (
      <span className={`px-2 py-1 rounded text-xs font-medium ${bgColor} ${textColor}`}>
        {status}
      </span>
    );
  };

  return (
    <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-white">Shot List</h2>
        
        <div className="flex space-x-2">
          <div className="relative">
            <input
              type="text"
              placeholder="Search shots..."
              className="bg-gray-800 border-gray-700 rounded pl-9 pr-4 py-2 text-white w-48"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-gray-400" />
          </div>
          
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="bg-gray-800 border-gray-700 rounded px-3 py-2 text-white"
          >
            <option value="All">All Statuses</option>
            <option value="Complete">Complete</option>
            <option value="In Progress">In Progress</option>
            <option value="Not Started">Not Started</option>
          </select>
          
          <select
            value={sceneFilter}
            onChange={(e) => setSceneFilter(e.target.value)}
            className="bg-gray-800 border-gray-700 rounded px-3 py-2 text-white"
          >
            {scenes.map(scene => (
              <option key={scene} value={scene}>{scene}</option>
            ))}
          </select>
          
          <button 
            className="flex items-center px-3 py-2 rounded text-white"
            style={{ backgroundColor: colors.accent }}
            onClick={() => document.getElementById('file-import').click()}
          >
            <Upload className="h-4 w-4 mr-1" />
            Import
          </button>
          <input 
            id="file-import" 
            type="file" 
            accept=".xlsx,.xls,.csv" 
            className="hidden"
            onChange={handleFileImport}
          />
          
          <button 
            className="flex items-center px-3 py-2 rounded text-white"
            style={{ backgroundColor: colors.darkAccent }}
          >
            <Download className="h-4 w-4 mr-1" />
            Export
          </button>
        </div>
      </div>
      
      {loading ? (
        <div className="text-center py-10">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-white"></div>
          <p className="text-white mt-2">Loading shots...</p>
        </div>
      ) : (
        <>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-gray-700">
                  <th className="px-4 py-3 text-left text-gray-400">Shot ID</th>
                  <th className="px-4 py-3 text-left text-gray-400">Scene</th>
                  <th className="px-4 py-3 text-left text-gray-400">Description</th>
                  <th className="px-4 py-3 text-left text-gray-400">Status</th>
                  <th className="px-4 py-3 text-left text-gray-400">Notes</th>
                  <th className="px-4 py-3 text-left text-gray-400">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredShots.map(shot => (
                  <tr key={shot.id} className="border-b border-gray-800">
                    <td className="px-4 py-3 text-white">{shot.id}</td>
                    <td className="px-4 py-3 text-white">{shot.scene}</td>
                    <td className="px-4 py-3 text-white">{shot.description}</td>
                    <td className="px-4 py-3">
                      <StatusBadge status={shot.status} />
                    </td>
                    <td className="px-4 py-3 text-gray-400 max-w-md truncate">{shot.notes}</td>
                    <td className="px-4 py-3">
                      <div className="flex space-x-2">
                        <select
                          className="bg-gray-800 text-white text-sm p-1 rounded border border-gray-700"
                          value={shot.status}
                          onChange={(e) => handleStatusChange(shot.id, e.target.value)}
                        >
                          <option value="Not Started">Not Started</option>
                          <option value="In Progress">In Progress</option>
                          <option value="Complete">Complete</option>
                        </select>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          
          <div className="mt-4 text-gray-400 text-right">
            Showing {filteredShots.length} of {shots.length} shots
          </div>
        </>
      )}
    </div>
  );
};

export default ShotList;
